#!/bin/bash
# Host-side verification of the GQ5012BF1 LineageOS 24 / Android 17 split product,
# iteration 3: ro.product.first_api_level is no longer hand-written into the system
# image; it is generated by the build system from PRODUCT_SHIPPING_API_LEVEL into
# the vendor-side property set (supplied at runtime by the untouched stock vendor).
set -o pipefail
TREE=/mnt/SamsungSSD/android/lineage-24.0
ART=/mnt/SamsungSSD/TIER3/phase5/android17
OUT="$ART/out-lineage_gsi_arm64-erofs"
P="$OUT/target/product/gq5012bf1"
STOCK_VENDOR=/mnt/SamsungSSD/TIER3/phase1/extracted/mounts/run-20260718T120318Z/vendor
ARCH=/mnt/WDBlue/TIER3-phase5-android17/split-iterations/i3-generated-properties
AVB="$OUT/host/linux-x86/bin/avbtool"
CHECKVINTF="$OUT/host/linux-x86/bin/checkvintf"
KEY4096="$TREE/external/avb/test/data/testkey_rsa4096.pem"
KEY2048="$TREE/external/avb/test/data/testkey_rsa2048.pem"
mkdir -p "$ARCH"

{
  echo "START=$(date -Is)"
  echo "PRODUCT=lineage_gq5012bf1 cp2a userdebug iteration-3 generated-first-api-level"

  echo '===== generated property audit (framework images)'
  for f in system/build.prop system_ext/etc/build.prop product/etc/build.prop; do
    echo "--- $f"
    grep -E '^(ro\.product|ro\.boot|ro\.system\.product|ro\.system\.ext\.product|ro\.product\.product)\.' "$P/$f" | sort -u
  done
  echo '===== runtime property source (untouched stock vendor)'
  grep -E 'first_api_level' "$STOCK_VENDOR/build.prop" | sort -u

  echo '===== checkvintf --check-compat (stock vendor + DSDS ODM)'
  "$CHECKVINTF" --check-compat \
    --dirmap /system:"$P/system" \
    --dirmap /vendor:"$STOCK_VENDOR" \
    --dirmap /odm:"$STOCK_VENDOR/odm" \
    --dirmap /product:"$P/product" \
    --dirmap /system_ext:"$P/system_ext" \
    --dirmap /apex:"$P/apex" \
    --property ro.product.first_api_level=35 \
    --property ro.vendor.api_level=34 \
    --property ro.boot.product.hardware.sku=dsds \
    --property ro.boot.product.vendor.sku=dsds > "$ARCH/checkvintf.log" 2>&1
  echo "checkvintf_rc=$? verdict=$(tail -1 "$ARCH/checkvintf.log")"
  tail -1 "$ARCH/checkvintf.log"

  echo '===== avbtool info_image (full)'
  for img in system system_ext product vbmeta_system vbmeta; do
    echo "--- $img.img"
    "$AVB" info_image --image "$P/$img.img" 2>&1 | sed 's/^ *//'
  done

  echo '===== avbtool verify_image (framework images)'
  for img in system system_ext product; do
    echo "--- $img.img"
    "$AVB" verify_image --image "$P/$img.img" 2>&1
  done

  echo '===== avbtool verify_image child vbmeta_system'
  "$AVB" verify_image --image "$P/vbmeta_system.img" --key "$KEY2048" 2>&1

  echo '===== avbtool extract_public_key (child signing key -> DER blob)'
  "$AVB" extract_public_key --key "$KEY2048" --output "$ARCH/vbmeta_system_pubkey.der"
  sha256sum "$ARCH/vbmeta_system_pubkey.der"

  echo '===== avbtool verify_image root vbmeta (follow chain)'
  "$AVB" verify_image --image "$P/vbmeta.img" \
    --expected_chain_partition "vbmeta_system:1:$ARCH/vbmeta_system_pubkey.der" \
    --follow_chain_partitions 2>&1

  echo '===== avbtool verify_image root vbmeta (no chain follow, key check)'
  "$AVB" verify_image --image "$P/vbmeta.img" --key "$KEY4096" \
    --expected_chain_partition "vbmeta_system:1:$ARCH/vbmeta_system_pubkey.der" 2>&1

  echo '===== artifact digests'
  for img in system system_ext product vbmeta_system vbmeta; do
    sha256sum "$P/$img.img"
  done
  echo '===== installed-file manifests'
  for f in installed-files.txt installed-files-system_ext.txt installed-files-product.txt; do
    sha256sum "$P/$f"
  done
  echo "END=$(date -Is)"
} 2>&1 | tee "$ARCH/verify.log"

rc=${PIPESTATUS[0]}
cp -f "$ART/logs/build-lineage_gq5012bf1-cp2a-userdebug-split-i3-generated-properties.rc" "$ARCH/build.rc"
cp -f "$ART/logs/configure-lineage_gq5012bf1-cp2a-userdebug-split-i1.log" "$ARCH/configure.vars" 2>/dev/null
cp -f "$ART/logs/build-lineage_gq5012bf1-cp2a-userdebug-split-i3-generated-properties.log" "$ARCH/build.log" 2>/dev/null
for f in installed-files.json installed-files.txt installed-files-system_ext.json installed-files-system_ext.txt installed-files-product.json installed-files-product.txt; do
  cp -f "$P/$f" "$ARCH/$f"
done
for img in system system_ext product vbmeta_system vbmeta; do
  cp -f "$P/$img.img" "$ARCH/$img.img"
done
printf 'build_rc=%s\nverify_rc=%s\n' "$(cat "$ARCH/build.rc")" "$rc" > "$ARCH/verify.rc"
echo "VERIFY_RC=$rc ARCHIVE=$ARCH"
exit "$rc"
